#!/bin/sh
# caret — command-line launcher for the Caret editor (like VS Code's `code`).
# Generated by Caret __CARET_VERSION__. Do not edit: Caret rewrites this file when the app moves or updates.
# Install/uninstall from the command palette: "Shell Command: Install 'caret' command in PATH".
BUNDLE_ID="__CARET_BUNDLE_ID__"
APP_PATH="__CARET_APP_PATH__"
VERSION="__CARET_VERSION__"

usage() {
  cat <<USAGE
Usage: caret [options] [paths...]

Open folders and files in Caret.

  caret                  launch or focus Caret
  caret .                open the current folder as the workspace
  caret src/app.ts       open a file (its folder becomes the workspace if none is open)
  caret -g app.ts:12:4   open a file at line 12, column 4 (a bare app.ts:12:4 works too)

Options:
  -g, --goto <file:line[:col]>   open a file at a position
  -n, --new-window               accepted for compatibility (Caret is single-window)
  -r, --reuse-window             accepted for compatibility
  -w, --wait                     accepted for compatibility (does not wait)
  -v, --version                  print the version
  -h, --help                     show this help
USAGE
}

is_num() { case "$1" in ''|*[!0-9]*) return 1 ;; esac; return 0; }

# Absolute, symlink-resolved path (so /tmp → /private/tmp matches what Caret shows). Missing files keep their name.
abspath() {
  p=$1
  case "$p" in
    "~") p=$HOME ;;
    "~/"*) p=$HOME/${p#"~/"} ;;
  esac
  case "$p" in /*) ;; *) p=$PWD/$p ;; esac
  if [ -d "$p" ]; then
    (cd -P -- "$p" 2>/dev/null && pwd) || printf '%s' "$p"
  else
    d=$(dirname -- "$p"); b=$(basename -- "$p")
    if [ -d "$d" ]; then
      rd=$(cd -P -- "$d" 2>/dev/null && pwd)
      case "$rd" in /) printf '/%s' "$b" ;; *) printf '%s/%s' "$rd" "$b" ;; esac
    else
      printf '%s' "$p"
    fi
  fi
}

# Percent-encode everything except unreserved characters and '/'.
urlencode() {
  printf '%s' "$1" | od -An -tx1 -v | tr ' ' '\n' | while read -r hex; do
    [ -z "$hex" ] && continue
    case "$hex" in
      2f|2d|2e|5f|7e|3[0-9]|4[1-9a-f]|5[0-9a]|6[1-9a-f]|7[0-9a]) printf "\\$(printf '%o' "0x$hex")" ;;
      *) printf '%%%s' "$hex" ;;
    esac
  done
}

# open_with_app <documents or URLs...> — hands them to Caret via LaunchServices; falls back to the app path.
open_with_app() {
  if [ -n "$CARET_CLI_DRY_RUN" ]; then
    printf 'open -b %s' "$BUNDLE_ID"; for x in "$@"; do printf ' %s' "$x"; done; printf '\n'; return 0
  fi
  if command -v open >/dev/null 2>&1; then
    open -b "$BUNDLE_ID" "$@" 2>/dev/null && return 0
    if [ -d "$APP_PATH" ]; then open -a "$APP_PATH" "$@" 2>/dev/null && return 0; fi
    echo "caret: could not launch Caret (bundle $BUNDLE_ID, app $APP_PATH). Launch Caret once from Finder and retry." >&2
    return 1
  fi
  # Not macOS: start the binary directly with the paths as arguments.
  bin=$APP_PATH; [ -x "$APP_PATH/Contents/MacOS/caret" ] && bin="$APP_PATH/Contents/MacOS/caret"
  "$bin" "$@" >/dev/null 2>&1 &
  return 0
}

# Split file:line[:col] from the right. Sets G_FILE, G_LINE, G_COL.
split_goto() {
  spec=$1; G_FILE=$spec; G_LINE=""; G_COL=""
  tail=${spec##*:}; head=${spec%:*}
  if [ "$head" != "$spec" ] && is_num "$tail"; then
    tail2=${head##*:}; head2=${head%:*}
    if [ "$head2" != "$head" ] && is_num "$tail2"; then G_FILE=$head2; G_LINE=$tail2; G_COL=$tail
    else G_FILE=$head; G_LINE=$tail; fi
  fi
}

PATHS=""; GOTOS=""; STATUS=0; NL='
'
add_path() {
  if [ -e "$1" ]; then PATHS="$PATHS$(abspath "$1")$NL"; return; fi
  split_goto "$1"
  if [ -n "$G_LINE" ] && [ -e "$G_FILE" ]; then add_goto "$1"; return; fi
  echo "caret: no such file or directory: $1" >&2; STATUS=1
}
add_goto() {
  split_goto "$1"
  if [ ! -e "$G_FILE" ]; then echo "caret: no such file or directory: $G_FILE" >&2; STATUS=1; return; fi
  if [ -d "$G_FILE" ]; then PATHS="$PATHS$(abspath "$G_FILE")$NL"; return; fi
  url="caret://open?path=$(urlencode "$(abspath "$G_FILE")")"
  [ -n "$G_LINE" ] && url="$url&line=$G_LINE"
  [ -n "$G_COL" ] && url="$url&col=$G_COL"
  GOTOS="$GOTOS$url$NL"
}

while [ $# -gt 0 ]; do
  case "$1" in
    -h|--help) usage; exit 0 ;;
    -v|--version) echo "caret $VERSION"; exit 0 ;;
    -g|--goto) shift; [ $# -gt 0 ] || { echo "caret: --goto needs a file:line[:col] argument" >&2; exit 2; }; add_goto "$1" ;;
    --goto=*) add_goto "${1#--goto=}" ;;
    -n|--new-window|-r|--reuse-window|-w|--wait|-a|--add|--) ;;
    -*) echo "caret: unknown option '$1'" >&2; usage >&2; exit 2 ;;
    *) add_path "$1" ;;
  esac
  shift
done

if [ -z "$PATHS" ] && [ -z "$GOTOS" ]; then
  [ $STATUS -eq 0 ] && open_with_app
  exit $STATUS
fi
if [ -n "$PATHS" ]; then
  # shellcheck disable=SC2086
  old_ifs=$IFS; IFS=$NL; set -f; set -- $PATHS; set +f; IFS=$old_ifs
  open_with_app "$@" || STATUS=1
fi
if [ -n "$GOTOS" ]; then
  old_ifs=$IFS; IFS=$NL; set -f; set -- $GOTOS; set +f; IFS=$old_ifs
  for u in "$@"; do open_with_app "$u" || STATUS=1; done
fi
exit $STATUS
